insert into kafaa_consortium_cohorts (id, code, title_en, title_ar, summary_en, summary_ar, intake_year, academy_id, nominations_close_on, starts_on, ends_on, partners, modules, project_en, project_ar, deliverable_en, deliverable_ar, mentors, skills, budget, currency, sources, simulated, synthetic, listed, sort) values
('cc-2026', 'UEC-2026', 'UAE Energy Trainee Cohort 2026–27', 'دفعة متدربي الطاقة في الإمارات 2026–2027', 'Six energy employers grow one graduate pool instead of competing for it: shared three-day modules hosted in turn at each member''s site, one joint project in mixed-employer teams, and a mentor from another employer. Partner organisations are synthetic; budgets are SIMULATED.', 'ستّ جهات عاملة في قطاع الطاقة تنمّي معاً قاعدة واحدة من الخريجين بدلاً من التنافس عليها: وحدات مشتركة مدة كل منها ثلاثة أيام تستضيفها كل جهة بالتناوب في موقعها، ومشروع مشترك في فرق مختلطة من جهات مختلفة، ومرشد من جهة أخرى. الجهات الشريكة افتراضية، والميزانيات مُحاكاة.', 2026, 'ac-energy', '2026-07-15', '2026-09-01', '2027-06-30', '[{"org_id":"enec-ops","code":"EN","role":"lead","name_en":"ENEC (lead employer)","name_ar":"مؤسسة الإمارات للطاقة النووية (الجهة الرائدة)","site_en":"Barakah training centre","site_ar":"مركز التدريب في براكة","visit_skill":"sk-fs-tr-techlit","seats":6,"kafaa_access":true,"synthetic":false},{"org_id":"org-cx-grid","code":"SG","role":"partner","name_en":"Sahel Grid Services (synthetic)","name_ar":"خدمات شبكة الساحل (افتراضي)","site_en":"Grid control and dispatch centre","site_ar":"مركز التحكم بالشبكة وتوزيع الأحمال","visit_skill":"sk-fs-gr-grid","seats":4,"kafaa_access":false,"synthetic":true},{"org_id":"org-cx-solar","code":"QS","role":"partner","name_en":"Qamar Solar Operations (synthetic)","name_ar":"قمر لتشغيل الطاقة الشمسية (افتراضي)","site_en":"Solar plant operations","site_ar":"تشغيل محطة الطاقة الشمسية","visit_skill":"sk-fs-gr-lifecycle","seats":4,"kafaa_access":false,"synthetic":true},{"org_id":"org-cx-h2","code":"RH","role":"partner","name_en":"Rimal Hydrogen and Heat Works (synthetic)","name_ar":"رمال لأعمال الهيدروجين والحرارة (افتراضي)","site_en":"Hydrogen and process-heat pilot","site_ar":"مشروع تجريبي للهيدروجين والحرارة الصناعية","visit_skill":"sk-fs-gr-h2heat","seats":4,"kafaa_access":false,"synthetic":true},{"org_id":"org-alnoor","code":"AN","role":"partner","name_en":"Al Noor Precision Engineering LLC (synthetic)","name_ar":"النور للهندسة الدقيقة (اصطناعية)","site_en":"Precision machining and module fabrication workshop","site_ar":"ورشة التشغيل الدقيق وتصنيع الوحدات","visit_skill":"sk-fs-adv-factoryqa","seats":3,"kafaa_access":true,"synthetic":true},{"org_id":"org-gulfhydro","code":"GH","role":"partner","name_en":"Gulf Hydro-Valve Industries LLC (synthetic)","name_ar":"الخليج للصمامات الهيدروليكية (اصطناعية)","site_en":"Valve manufacturing and remote-inspection test bay","site_ar":"تصنيع الصمامات ومنصة اختبار الفحص عن بُعد","visit_skill":"sk-fs-dp-robotics","seats":3,"kafaa_access":true,"synthetic":true}]'::jsonb, '[{"id":"m1","host_org_id":"enec-ops","starts_on":"2026-09-14","ends_on":"2026-09-16","title_en":"Nuclear plant fundamentals and safety culture","title_ar":"أساسيات المحطة النووية وثقافة السلامة","course_id":"c-fs-plantlit-x"},{"id":"m2","host_org_id":"org-cx-grid","starts_on":"2026-10-05","ends_on":"2026-10-07","title_en":"Grid integration and flexible operation","title_ar":"التكامل مع الشبكة والتشغيل المرن","course_id":"c-fs-systems"},{"id":"m3","host_org_id":"org-cx-solar","starts_on":"2026-11-16","ends_on":"2026-11-18","title_en":"Lifecycle carbon and GHG accounting","title_ar":"الكربون على امتداد دورة الحياة ومحاسبة الانبعاثات","course_id":"c-fs-ghg"},{"id":"m4","host_org_id":"org-cx-h2","starts_on":"2027-01-18","ends_on":"2027-01-20","title_en":"Hydrogen and process heat","title_ar":"الهيدروجين والحرارة الصناعية","course_id":"c-fs-h2heat"},{"id":"m5","host_org_id":"org-alnoor","starts_on":"2027-03-15","ends_on":"2027-03-17","title_en":"Factory fabrication QA for modular builds","title_ar":"ضمان الجودة في التصنيع بالمصنع للبناء المعياري","course_id":"c-fs-factoryqa"},{"id":"m6","host_org_id":"org-gulfhydro","starts_on":"2027-05-17","ends_on":"2027-05-19","title_en":"Remote inspection, robotics and the project showcase","title_ar":"الفحص عن بُعد والروبوتات وعرض المشروع","course_id":null}]'::jsonb, 'Run one SIMULATED 24-hour energy system with nuclear, solar, grid and hydrogen: each mixed-employer team works out what the operators at one site need to know about the others, and where a hand-off between sites could fail.', 'تشغيل منظومة طاقة مُحاكاة على مدى 24 ساعة تضم الطاقة النووية والشمسية والشبكة والهيدروجين: يحدد كل فريق مختلط ما يحتاج المشغّلون في موقع واحد إلى معرفته عن المواقع الأخرى، وأين قد يتعثر التسليم بين المواقع.', 'A team study with its assumptions and a short briefing to the consortium board at the final module. SIMULATED data only.', 'دراسة فريق تتضمن افتراضاتها وإحاطة قصيرة لمجلس الاتحاد في الوحدة الأخيرة. بيانات مُحاكاة فقط.', '[{"id":"mt-en-1","org_id":"enec-ops","label_en":"Senior reactor operator mentor (role card)","label_ar":"مرشد مشغّل مفاعل أول (بطاقة دور)"},{"id":"mt-en-2","org_id":"enec-ops","label_en":"Training engineer mentor (role card)","label_ar":"مرشد مهندس تدريب (بطاقة دور)"},{"id":"mt-sg-1","org_id":"org-cx-grid","label_en":"Grid control mentor (role card)","label_ar":"مرشد التحكم بالشبكة (بطاقة دور)"},{"id":"mt-qs-1","org_id":"org-cx-solar","label_en":"Solar operations mentor (role card)","label_ar":"مرشد تشغيل الطاقة الشمسية (بطاقة دور)"},{"id":"mt-rh-1","org_id":"org-cx-h2","label_en":"Process-heat engineer mentor (role card)","label_ar":"مرشد مهندس الحرارة الصناعية (بطاقة دور)"},{"id":"mt-an-1","org_id":"org-alnoor","label_en":"Fabrication QA mentor (role card)","label_ar":"مرشد ضمان جودة التصنيع (بطاقة دور)"},{"id":"mt-gh-1","org_id":"org-gulfhydro","label_en":"Valve test mentor (role card)","label_ar":"مرشد اختبار الصمامات (بطاقة دور)"}]'::jsonb, array['sk-fs-tr-techlit','sk-fs-gr-grid','sk-fs-gr-lifecycle','sk-fs-gr-h2heat','sk-fs-adv-factoryqa','sk-fs-dp-robotics','sk-fs-tr-crosscultural','sk-fs-tr-systems']::text[], '[{"org_id":"enec-ops","amount":360000},{"org_id":"org-cx-grid","amount":120000},{"org_id":"org-cx-solar","amount":120000},{"org_id":"org-cx-h2","amount":120000},{"org_id":"org-alnoor","amount":60000},{"org_id":"org-gulfhydro","amount":60000}]'::jsonb, 'AED', '[{"label":"Fortum · Nordic Nuclear Trainee Programme (NNTP)","url":"https://www.fortum.com/careers/NNTP","as_of":"2026-10-10","secondary":true},{"label":"WAM · EGA launches EGA Academy","url":"https://www.wam.ae/en/article/blmzwis-ega-launches-ega-academy","as_of":"2026-10-10","secondary":false}]'::jsonb, true, true, true, 1),
